import type { ExamQuestion } from "@/lib/exam-bank";

/**
 * Approved IFRSQuiz items are generated by scripts/publish-ifrsquiz-questions.mjs
 * from a permission-backed source export after bilingual review.
 * The public catalogue advertises 665 external items, but the site has not
 * supplied their question/answer text to this build. DO NOT fabricate entries.
 * A zero-length array is deliberate and keeps local bank totals honest.
 */
export const IFRSQUIZ_IMPORTED_QUESTIONS: ExamQuestion[] = [];

export interface IfrsQuizQuestionProvenance {
  sourceUrl: string;
  sourceRevision: string;
  sourceLicense: string;
  sourceItemId: string;
  sourceFingerprint: string;
  sourceAnswerKey: string | number;
}

export const IFRSQUIZ_QUESTION_PROVENANCE: Readonly<Record<string, IfrsQuizQuestionProvenance>> = {};
